"""Stage playbooks 0-4. step = (what, how, proof)."""
def stages():
    S = []
    S.append(dict(n=0, title="Get Ready", phase="Discover", gate=None, time="Day 1–2",
      goal="Have every account, tool and permission working so nothing blocks you later.",
      start="You have joined, or been assigned a project, and your manager has given you a Project ID (for example P001).",
      who="You · Tech Lead (approves) · Owner (creates accounts)", tools="Password manager, authenticator app, VS Code, Git, Node.js LTS, browser, API client, database client",
      skills="None. This stage teaches the basics.",
      steps=[
       ("Read Parts 1–5 of this handbook","Read slowly. Write down every word you do not understand and look it up in Part 5 (Glossary). About 2 hours.","Tick 'I have read the handbook' on your onboarding sheet"),
       ("Set up your company accounts","Use only your company email. Create a password manager account; use a different long password for every service. Turn on <b>MFA</b> (two-factor) on email, GitHub, hosting and domain accounts using an <b>authenticator app</b> (not SMS). Store recovery codes in the company's shared vault, never in chat or on paper left on a desk.","Screenshot of MFA 'enabled' on each account (hide codes)"),
       ("Install the standard tools","Download only from the official sites: VS Code, Git, Node.js (choose LTS), Postman or Bruno, DBeaver or pgAdmin. Then open a terminal and run <code>git --version</code>, <code>node --version</code>, <code>npm --version</code>. Each must print a version number.","Paste the 3 version outputs in your onboarding sheet"),
       ("Set up VS Code","Install extensions: ESLint, Prettier, GitHub Pull Requests. In Settings turn on <i>Format on Save</i>. Learn 5 shortcuts: open file (Ctrl+P), search all (Ctrl+Shift+F), terminal (Ctrl+`), command palette (Ctrl+Shift+P), multi-cursor (Alt+Click).","VS Code opens a folder and formats a file on save"),
       ("Tell Git who you are and create an SSH key","<code>git config --global user.name \"Your Name\"</code> then <code>git config --global user.email \"you@company.com\"</code>. Create a key: <code>ssh-keygen -t ed25519 -C \"you@company.com\"</code> (press Enter to accept defaults, set a passphrase). Copy the <i>.pub</i> file contents into GitHub → Settings → SSH keys. Test: <code>ssh -T git@github.com</code> should greet you by username.","Greeting message from the test command"),
       ("Get access to company systems","Ask the Tech Lead for: GitHub organisation invite, the board (tickets), the shared drive (Part 2), the dashboard, the staging environment URL. Open each one and confirm you can see your project.","Access checklist ticked by Tech Lead"),
       ("Create your work folders","Make <code>~/work/</code> (Windows: <code>C:\\work\\</code>) and inside it your project folder named with the Project ID. Never keep code on the Desktop or in personal cloud folders.","Folder exists; matches Part 2.2"),
       ("Start your timesheet","Every day log: Project ID, stage number, hours, 1-line note. Do it before you leave, not at month end.","First day entry saved"),
       ("Do the practice task","Clone the <code>training-sandbox</code> repository, create a branch <code>feature/0-your-name</code>, change one line in the README, commit, push, open a Pull Request and ask for review. This proves the full workflow works for you.","Link to your merged practice Pull Request")],
      selfcheck=["MFA is on for every account","I can run git, node and npm","SSH test greets me by username","I can open the board, drive, repo and dashboard","My practice Pull Request was reviewed and merged","I know where to log time"],
      signoff="Tech Lead checks the onboarding sheet and your practice Pull Request.",
      errors=[("Used personal email to sign up","Ask Owner to move the account to the company email and rotate the password"),("MFA by SMS only","Switch to authenticator app; keep recovery codes in the shared vault"),("'git' is not recognised","Close and reopen the terminal after installing; if still failing, reinstall and tick 'add to PATH'"),("Permission denied (publickey)","The public key was not added to GitHub, or you copied the wrong file (.pub, not private)")],
      example="You are assigned P001-slotwise. By the end of Day 2 you can clone its repository, run it locally, and your first tiny Pull Request has been merged.",
      learn=[("Pro Git book","https://git-scm.com/book/en/v2"),("GitHub docs: SSH","https://docs.github.com/en/authentication/connecting-to-github-with-ssh")]))
    S.append(dict(n=1, title="Check the Idea", phase="Discover", gate="G1 – Opportunity Approval", time="2–3 weeks",
      goal="Prove that real people have this problem and will pay to solve it, before the company spends money building.",
      start="The Owner has given you an idea or a market to explore, and a Project ID.",
      who="Product Owner (leads) · Researcher / you · Owner (approves G1)", tools="Spreadsheet, Google, G2, Capterra, Product Hunt, Reddit, Google Trends, phone/video calls, notes",
      skills="Basic spreadsheet use, polite conversation.",
      steps=[
       ("Write the problem in one sentence","Use this template: <b>\"[Who] struggle to [do what] because [reason], which costs them [time or money].\"</b> Example: \"Small clinic receptionists struggle to manage appointments on paper because calls are missed, which costs the clinic patients.\" If you cannot fill all four blanks, you do not understand the problem yet.","Sentence at top of the research report"),
       ("Choose the customer segment and name three people","Write who the <b>buyer</b> (pays), the <b>user</b> (uses daily) and the <b>decision-maker</b> (says yes) are. They are often three different people. Describe the ideal customer in 5 lines: size, location, tools they use now, budget owner.","Ideal Customer Profile (ICP) box"),
       ("Find 5–10 competitors","Search Google; browse G2, Capterra, Product Hunt categories; ask in relevant Reddit/professional groups. For each product open its website, features page and <b>pricing page</b>. Copy into a sheet: name, link, <b>date you visited</b>, target customer, plans and prices, free trial, main features, review score and number of reviews, weaknesses customers complain about. <b>Never type a price from memory.</b>","Competitor sheet + dated screenshots"),
       ("Compare and find the gap","Make a table: features down the side, competitors across. Mark what each does well/badly. Underline what customers want but nobody does well. That gap is your reason to exist.","Comparison table + 3-line 'our difference'"),
       ("Interview at least 10 target customers","Ask permission first. Ask about <b>what they did last time</b>, not opinions. Five questions: (1) Tell me about the last time this problem happened. (2) What did you do about it? (3) What does it cost you? (4) What do you use today and what do you pay? (5) If a tool solved this, what would you pay? Write notes in the Customer Discovery template.","10 interview notes with date, role, quotes, consent"),
       ("Test willingness to pay","Ask the buyer: 'If we offered X at ₹Y per month, would you do a paid pilot?' Record the answer exactly. 'Sounds nice' is <b>not</b> a yes. A pilot commitment or letter of intent is a yes.","Count of pilot commitments"),
       ("Estimate the market (bottom-up)","<b>TAM</b> = number of possible customers × yearly price per customer. <b>SAM</b> = the part you can really reach (city, size, language). <b>SOM</b> = what you can win in 3 years with your sales capacity. Get the number of customers from a government or industry source and save the link + date. If none exists, write <b>ASSUMPTION</b> next to it. Never invent a number.","TAM/SAM/SOM sheet with sources"),
       ("Estimate how hard selling will be","Note how customers buy (word of mouth, search, demos), how long a deal takes (days/weeks), and what a customer costs to find (CAC range). This feeds Stage 9.","Sales-cycle paragraph"),
       ("List ways to earn recurring revenue","Subscription tiers, extra usage fees, onboarding fee, support plans, add-on modules.","Revenue ideas list"),
       ("Write the Market Research Report (2–4 pages)","Sections: 1 Problem sentence · 2 Customer (ICP) · 3 Evidence from interviews · 4 Competitors table + gap · 5 Market size with sources · 6 Sales difficulty · 7 Revenue options · 8 Risks · 9 Recommendation: <b>GO / NO-GO / CHANGE DIRECTION</b> with reasons.","Report PDF saved in 01-research"),
       ("Submit Gate G1","Upload the report to the dashboard and request approval. The Owner reads it and decides. Do not start Stage 2 until G1 is signed.","G1 signed")],
      selfcheck=["Problem sentence has all four blanks filled","At least 5 competitors with link + date","At least 10 customer interviews with notes","Every number has a source link or is marked ASSUMPTION","Buyer, user and decision-maker named","At least 3 of 10 prospects confirmed the problem is a top-3 priority","A clear GO / NO-GO recommendation is written"],
      signoff="Owner signs G1. Kill rule: if fewer than 3 of 10 prospects confirm the pain, or nobody will pay near the break-even price, the answer is NO-GO.",
      errors=[("Only talking to friends","Interview strangers who match the ICP"),("Copying competitors' features","Start from the customer's pain, then pick features"),("'The market is huge'","Use bottom-up: customers × price"),("Prices from blogs","Use the competitor's own pricing page; note the date")],
      example="SlotWise: problem sentence written; 8 competitor pages recorded with dates; 10 clinic owners interviewed; 4 agreed to a paid pilot → recommendation GO, Owner signs G1.",
      learn=[("G2 (software reviews)","https://www.g2.com/"),("Capterra","https://www.capterra.com/"),("Google Trends","https://trends.google.com/")]))
    S.append(dict(n=2, title="Write What We Will Build", phase="Define", gate="G2 – Scope Freeze", time="2–3 weeks",
      goal="Write down exactly what will be built, so everyone builds the same thing and later changes are controlled.",
      start="G1 is signed.", who="Product Owner (writes) · Tech Lead (checks feasibility) · QA (checks testability) · Customer (approves)",
      tools="Documents, spreadsheet, Figma (journeys), PRD and Input-Output templates", skills="Clear writing, basic spreadsheet.",
      steps=[
       ("Copy the PRD template","From <code>00-company/templates/</code> into <code>02-requirements/</code>. Rename with the naming rule: <code>P001_PRD_v0.1_date</code>.","File created"),
       ("Write purpose and users","Purpose: 3 sentences. Then a table of <b>roles</b> (e.g. Owner, Receptionist, Doctor, Patient, Platform Admin) with a one-line description each.","Purpose + roles table"),
       ("List modules and user stories","A module is a group of features (Booking, Reminders, Patients, Billing, Reports, Admin). For each feature write: <b>\"As a [role] I want [action] so that [benefit].\"</b>","Module list with stories"),
       ("Make the permission matrix","Rows = actions (create, view, edit, delete, export), columns = roles. Put ✓ or ✗. The developers will turn this into server checks.","Permission table"),
       ("Write user journeys","For each role write numbered steps from opening the app to reaching their goal. Example: 1 Receptionist logs in → 2 opens calendar → 3 picks free slot → 4 enters patient → 5 saves → 6 sees confirmation.","One journey per role"),
       ("Write the Input specification","One spreadsheet row per field: <b>name · type · unit · required? · default · validation rule · minimum · maximum · where the data comes from · database column</b>. Example: <i>patient_phone · text · international format · yes · none · must match +country code, 8–15 digits · – · booking form · patients.phone</i>.","Input sheet complete"),
       ("Write the Output specification","One row per screen, report, email or API response: <b>name · format · how it is calculated · decimal places · where shown · export format (PDF/CSV) · what happens on error</b>. Example: No-show rate = no-shows ÷ (completed + no-shows), 1 decimal, shown on Reports, export CSV, if denominator is 0 show 0.0%.","Output sheet complete"),
       ("Write acceptance criteria","For each feature at least two scenarios in <b>Given / When / Then</b> form: one normal, one error. Example: Given slot 10:15 is taken, When another patient books 10:15, Then the system refuses and offers the next three free slots.","Criteria under each feature"),
       ("Add measurable non-functional requirements","Numbers, not adjectives: page loads in under 3 seconds on mobile data; API answers in under 500 ms for 95% of requests; data backed up daily; works on the last two versions of Chrome, Edge, Safari, Firefox; layout works from 360 px width.","NFR table"),
       ("Create sample input → output scenarios","At least 3 worked examples with real-looking fake numbers; QA will use them as tests.","Scenario table"),
       ("Review and freeze","Hold a review meeting with the Tech Lead, QA and customer. Fix every comment. Stamp the documents <b>v1.0</b> with date and get signatures. From now on every change needs a <b>Change Request</b> (Appendix A) with: ID, reason, technical impact, cost impact, time impact, security impact, customer approval, PO approval.","G2 signed; scope frozen")],
      selfcheck=["All roles and permissions written","Every input and output is specified in the sheets","Every feature has at least 2 acceptance criteria","Out-of-scope list written","Numbers (not words) in non-functional requirements","Sample scenarios included","Customer and Product Owner have signed"],
      signoff="Product Owner and Customer sign G2. After this, nobody writes code until Stage 5 is complete.",
      errors=[("'Fast', 'easy', 'modern'","Replace with numbers"),("Forgetting error cases","Every feature gets one 'what if it goes wrong' scenario"),("Adding features after freeze","Open a Change Request; the PO decides with cost and time impact")],
      example="SlotWise: 6 modules, 31 user stories, 4 roles, 22 input fields, 9 outputs, 74 acceptance criteria, signed as v1.0.",
      learn=[("OWASP ASVS (security requirements)","https://asvs.owasp.org/")]))
    S.append(dict(n=3, title="Plan How It Will Work", phase="Define", gate="G3 – Architecture Approval", time="1–2 weeks",
      goal="Decide the technology and the design of the system and database in a way that is simple, secure and affordable.",
      start="G2 is signed.", who="Tech Lead (owns) · Senior developer (reviews) · DevOps (hosting/cost input)", tools="draw.io or Excalidraw, ERD tool (dbdiagram.io), spreadsheet, document template", skills="Basic understanding of web apps and tables.",
      steps=[
       ("Read the PRD and list technical questions","How many users? What sensitive data (names, phones, health, payments)? Which outside services (email, SMS, payment)? Any legal duties? Write answers; they drive every choice.","Question list answered"),
       ("Start from the company default stack","Default: <b>TypeScript, React/Next.js, Node.js, PostgreSQL, an ORM with migrations</b>, hosted on a managed platform. Use something else only if the Tech Lead approves with a written reason.","Stack decision line"),
       ("Compare two architecture options","Score each 1–5 on cost to build, cost to host, cost to maintain, scalability, security, performance, availability of developers, lock-in, integration fit. Multiply by weights (add to 100%). Start with a <b>modular monolith</b> (one app, clear modules inside); choose microservices only with written proof you need them.","Scoring table + winner"),
       ("Draw the system diagram","Boxes: Browser → Web app → API → Database; plus Email service, SMS/WhatsApp, Payment gateway, File storage, Background jobs, Monitoring. Arrows show who talks to whom.","System diagram file in 03-architecture"),
       ("Design the database (ERD)","List the 'things' (patients, appointments, doctors) – each becomes a <b>table</b>. For each table list columns and their type. Every table gets <code>id</code>, <code>created_at</code>, <code>updated_at</code>; tables that belong to a customer get <code>tenant_id</code>. Draw lines for relationships (one doctor has many appointments). Never store passwords in readable form.","ERD + data dictionary (table, column, type, meaning)"),
       ("List the API endpoints","Table: method (GET read, POST create, PUT/PATCH change, DELETE) · path (e.g. <code>/api/appointments</code>) · who may call · input · output · possible errors. Use nouns in plural, versions like <code>/api/v1/</code>.","API list in docs/api"),
       ("Design login and roles","How users sign in; passwords stored hashed using a trusted library (never invent your own); sessions or tokens expire; role checks happen on the <b>server</b>, never only in the screen.","Auth design page"),
       ("Write a one-page threat model","Table: what could go wrong (someone sees another customer's data, guesses passwords, spams the booking page, steals a file) → how we stop it → how we test it.","Threat table"),
       ("Plan environments, backups and hosting","Local, staging, production; each with separate database and secrets. Backups: how often, how long kept, who restores. Ask DevOps for hosting options and cost (feeds Stage 9).","Infrastructure diagram"),
       ("Write the Architecture Document and decisions","Combine diagrams, ERD, API list, auth, threat model and a short 'Decision record' per big choice (what, why, alternatives). Present to the Tech Lead and Owner.","G3 signed")],
      selfcheck=["Two options scored and the winner explained","Diagrams match the PRD (nothing missing, nothing extra)","Every table has id, created_at, updated_at; tenant data has tenant_id","API list covers every PRD feature","Login, roles and secrets handling written","Backups and restore plan written","Threat model has at least 8 rows"],
      signoff="Tech Lead and Owner sign G3. Changing the stack later needs a written decision record and a Change Request.",
      errors=[("Choosing technology because it is popular","Use the scoring table"),("One giant table for everything","Split into tables per 'thing' and link them"),("Role checks only in the screen","Always enforce on the server")],
      example="SlotWise: Option A (Next.js + Node/TS modular monolith + PostgreSQL on managed hosting) scored 3.80 vs Option B 3.60; chosen.",
      learn=[("PostgreSQL tutorial","https://www.postgresql.org/docs/current/tutorial.html"),("OWASP Top 10","https://owasp.org/www-project-top-ten/")]))
    S.append(dict(n=4, title="Design the Screens", phase="Define", gate="G4 – Design Approval", time="2–4 weeks",
      goal="Draw every screen and test it with real users before any code is written, because changing a drawing costs minutes and changing code costs days.",
      start="G3 is signed (or in parallel once G2 is signed, as agreed by the PO).", who="UI/UX Designer (leads) · Product Owner · Frontend developer · Customer",
      tools="Figma, pen and paper, contrast checker (WebAIM), Lighthouse", skills="Basic design sense; Figma is taught in-house.",
      steps=[
       ("Make the sitemap","A tree of every page: Login → Dashboard → Calendar → New booking → Patients → Reports → Settings. Take it from the user journeys in the PRD.","Sitemap"),
       ("Draw the user flows","For each journey draw boxes and arrows with decisions ('slot free?'). Check every PRD journey appears.","Flow diagrams"),
       ("Sketch low-fidelity wireframes","Grey boxes only: no colour, no pictures. Place navigation, titles, forms, tables, buttons. Review with the PO. Wireframes are cheap; change them freely.","Wireframes for every page"),
       ("Define the design system","Choose: colours (primary, text, background, success, warning, error), fonts and sizes, spacing scale (4/8/16/24 px), corner radius. Check text contrast is at least <b>4.5:1</b> (WCAG AA) with a contrast checker. Create reusable components: button, input, select, table, modal, toast message.","Design system page in Figma"),
       ("Design the high-fidelity screens","Apply the design system to each wireframe. For each screen also design the <b>empty state</b> (no data yet), <b>loading</b>, <b>error</b>, and <b>success</b> states. Avoid heavy animation and decorative gradients.","Hi-fi screens with all states"),
       ("Design the mobile layouts","Design at 360 px, 768 px and 1280 px. Buttons at least 44×44 px for touch. Check text is readable without zoom.","Responsive frames"),
       ("Build a clickable prototype","Link screens in Figma so a user can click through the main journey.","Prototype link"),
       ("Test with 5 target users","Give each user 5 tasks ('book a patient for 10:15'). Do not help. Note: task finished? how long? where confused? quotes. Fix every problem that stopped 2 or more users.","Usability report"),
       ("Check accessibility basics","Everything reachable by keyboard; labels on inputs; colour never the only signal; alt text for images.","Accessibility checklist ticked"),
       ("Hand over to developers","Name components consistently, export icons/images, add notes for behaviour. Present to PO and customer and get approval.","G4 signed")],
      selfcheck=["Every PRD journey has screens","Empty, loading, error and success states designed","Contrast at least 4.5:1 for text","Mobile layouts done","Usability test with 5 users completed and fixes made","Customer approved the prototype"],
      signoff="Product Owner and Customer sign G4. Design changes afterwards go through change control.",
      errors=[("Designing only the happy path","Add error and empty states for every screen"),("Tiny buttons on mobile","Minimum 44×44 px"),("Using real customer data in designs","Use fake data")],
      example="SlotWise: 14 screens × 3 sizes; 5 receptionists tested; the 'next free slot' button was moved after 3 of 5 missed it.",
      learn=[("WCAG 2.2","https://www.w3.org/TR/WCAG22/"),("web.dev Learn","https://web.dev/learn")]))
    return S
